// forward declarations - TS hoists function declarations, C++ does not
void testSort();

void testSort()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // empty array
    assertDeepEqual(exchange, std::any{}, std::string("sort"), exchange.sort(ccxt::list{}), ccxt::list{});
    // single element
    assertDeepEqual(exchange, std::any{}, std::string("sort"), exchange.sort(ccxt::list{std::string("a")}), ccxt::list{std::string("a")});
    // already sorted (idempotent)
    assertDeepEqual(exchange, std::any{}, std::string("sort"), exchange.sort(ccxt::list{std::string("a"), std::string("b"), std::string("c")}), ccxt::list{std::string("a"), std::string("b"), std::string("c")});
    // duplicates
    assertDeepEqual(exchange, std::any{}, std::string("sort"), exchange.sort(ccxt::list{std::string("b"), std::string("a"), std::string("b"), std::string("c")}), ccxt::list{std::string("a"), std::string("b"), std::string("b"), std::string("c")});
    assertDeepEqual(exchange, std::any{}, std::string("sort"), exchange.sort(ccxt::list{std::string("b"), std::string("a"), std::string("c"), std::string("d")}), ccxt::list{std::string("a"), std::string("b"), std::string("c"), std::string("d")});
    // todo 1: atm, `sort` is only meant for strings. we should update to support numerics
    // todo 2: add test for above 10, eg: 1, 2, 10, 20, 21
    // // integers (single-digit, safe for cross-language lexicographic/numeric consistency)
    // assertDeepEqual (exchange, undefined, 'sort', exchange.sort ([ 3, 1, 2 ]), [ 1, 2, 3 ]);
    // assertDeepEqual (exchange, undefined, 'sort', exchange.sort ([ 5, 3, 1, 4, 2 ]), [ 1, 2, 3, 4, 5 ]);
    // assertDeepEqual (exchange, undefined, 'sort', exchange.sort ([ 0, 3, 1, 2 ]), [ 0, 1, 2, 3 ]);
    // // floats (values chosen so lexicographic order matches numeric order)
    // assertDeepEqual (exchange, undefined, 'sort', exchange.sort ([ 1.5, 0.5, 2.5 ]), [ 0.5, 1.5, 2.5 ]);
    // assertDeepEqual (exchange, undefined, 'sort', exchange.sort ([ 3.3, 1.1, 2.2 ]), [ 1.1, 2.2, 3.3 ]);
    // immutability - original array should not be modified
    std::any original = ccxt::list{std::string("b"), std::string("a"), std::string("c")};
    exchange.sort(original);
    assertDeepEqual(exchange, std::any{}, std::string("sort"), original, ccxt::list{std::string("b"), std::string("a"), std::string("c")});
}

